begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
insert into auth.users(id,email) values ('10000000-0000-4000-8000-000000000001','goal-a@example.test'),('10000000-0000-4000-8000-000000000002','goal-b@example.test');
insert into auth.sessions(id,user_id) values ('20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001'),('20000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000002');
insert into finance.profiles(id,display_name) values ('10000000-0000-4000-8000-000000000001','Synthetic A'),('10000000-0000-4000-8000-000000000002','Synthetic B');
insert into finance.households(id,name) values ('30000000-0000-4000-8000-000000000001','Synthetic A'),('30000000-0000-4000-8000-000000000002','Synthetic B');
insert into finance.household_members(id,household_id,user_id,display_name) values ('40000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','Synthetic A'),('40000000-0000-4000-8000-000000000002','30000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000002','Synthetic B');
create function pg_temp.command() returns jsonb language sql as $$select '{"id":"50000000-0000-4000-8000-000000000001","householdId":"30000000-0000-4000-8000-000000000001","ownership":{"kind":"HOUSEHOLD"},"name":"Synthetic goal","target":{"amount":"30000","currency":"ILS"},"declared":{"amount":"6000.0","currency":"ILS"},"monthly":null,"targetDate":"2027-10-31","action":"CREATE","expectedVersion":0,"acknowledge":true,"idempotencyKey":"synthetic-goal-command"}'::jsonb$$;
select ok(not has_function_privilege('anon','api.save_goal(jsonb)','EXECUTE'),'anonymous command denied');
select ok(not has_function_privilege('anon','api.goals_snapshot()','EXECUTE'),'anonymous read denied');
select ok(not has_table_privilege('authenticated','finance.goals','INSERT'),'no direct head create');
select ok(not has_table_privilege('authenticated','finance.goals','UPDATE'),'no direct head update');
select ok(not has_table_privilege('authenticated','finance.goal_revisions','INSERT'),'no direct revision create');
select ok(not has_table_privilege('authenticated','finance.goal_revisions','DELETE'),'no direct revision delete');
select ok(not has_table_privilege('authenticated','private.goal_receipts','SELECT'),'private receipt hidden');
select ok(not has_table_privilege('authenticated','private.goal_audit','SELECT'),'private audit hidden');
select ok(not prosecdef and provolatile='s','stable invoker snapshot') from pg_proc where oid='api.goals_snapshot()'::regprocedure;
select is((select proconfig[1] from pg_proc where oid='private.save_goal(jsonb)'::regprocedure),'search_path=""','fixed empty writer search path');
set local role anon;
select throws_ok('select api.goals_snapshot()','42501',null,'anonymous call denied');
set local role authenticated;
select is(api.save_goal(pg_temp.command())->'error'->>'code','NOT_AUTHORIZED','missing session write denied');
select is(api.goals_snapshot()->'error'->>'code','NOT_AUTHORIZED','missing session read denied');
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000001","role":"authenticated","session_id":"20000000-0000-4000-8000-000000000001"}',true);
select is(api.save_goal(pg_temp.command())->>'version','1','create goal');
select is(api.save_goal(pg_temp.command())->>'version','1','exact retry');
select is((select count(*) from finance.goal_revisions),1::bigint,'one revision');
select is(api.save_goal(pg_temp.command()||'{"name":"Changed"}')->'error'->>'code','CONFLICT','changed complete payload');
select is(api.save_goal(pg_temp.command()||'{"householdId":"30000000-0000-4000-8000-000000000002"}')->'error'->>'code','NOT_AUTHORIZED','foreign household write denied');
select is(api.save_goal(pg_temp.command()||'{"id":"50000000-0000-4000-8000-000000000002","idempotencyKey":"synthetic-goal-personal","ownership":{"kind":"MEMBER","memberId":"40000000-0000-4000-8000-000000000002"}}')->'error'->>'code','INVALID_INPUT','foreign member denied');
select is(api.save_goal(pg_temp.command()||'{"action":"EDIT","expectedVersion":1,"idempotencyKey":"synthetic-goal-edit","declared":{"amount":"0","currency":"ILS"}}')->>'version','2','zero declaration edit');
select is(api.save_goal(pg_temp.command()||'{"action":"EDIT","expectedVersion":1,"idempotencyKey":"synthetic-goal-stale"}')->'error'->>'code','CONFLICT','stale edit rejected');
select is(api.save_goal(pg_temp.command()||'{"action":"ARCHIVE","expectedVersion":2,"idempotencyKey":"synthetic-goal-archive","declared":{"amount":"0.000","currency":"ILS"}}')->>'version','3','canonical-equivalent archive');
select is(api.save_goal(pg_temp.command()||'{"action":"EDIT","expectedVersion":3,"idempotencyKey":"synthetic-goal-terminal"}')->'error'->>'code','CONFLICT','archive terminal');
select is(api.goals_snapshot()->'snapshot'->>'size','5','full bounded planning snapshot count');
select is((select count(*) from finance.goal_revisions),3::bigint,'immutable history retained');
select throws_ok($$update finance.goal_revisions set body='{}'::jsonb$$,'42501',null,'direct revision update denied');
select throws_ok($$delete from finance.goals$$,'42501',null,'direct head delete denied');
select throws_ok($$select * from private.goal_audit$$,'42501',null,'audit inaccessible');
reset role;
select throws_ok($$update finance.goal_revisions set body='{}'::jsonb$$,'23514',null,'immutable history trigger');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000002","role":"authenticated","session_id":"20000000-0000-4000-8000-000000000002"}',true);
select is((select count(*) from finance.goal_revisions),0::bigint,'household RLS read isolation');
select is(jsonb_array_length(api.goals_snapshot()->'snapshot'->'revisions'),0,'snapshot read isolation');
reset role;
update finance.household_members set status='REVOKED' where user_id='10000000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000001","role":"authenticated","session_id":"20000000-0000-4000-8000-000000000001"}',true);
select is(api.save_goal(pg_temp.command())->'error'->>'code','NOT_AUTHORIZED','revoked exact receipt denied');
select is(jsonb_array_length(api.goals_snapshot()->'snapshot'->'revisions'),0,'revoked data hidden');
select * from finish();
rollback;
